'use strict';
const M=globalThis.AD03Model;
const App=(()=>{
const KEY='ppo.ad03.r01.workspace',UIKEY='ppo.ad03.r01.view';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>'<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">'+(ICONS[n]||ICONS.info)+'</svg>';
const button=(action,label,cl='',attrs='')=>`<button type="button" data-action="${action}" class="${cl}" ${attrs}>${label}</button>`;
const badge=(t,cl='')=>`<span class="tag ${cl||(/unknown|Missing|Partial|Needs|Returned|Date needed|Overdue|Stale/.test(t)?'warning':/Closed|Applied|Accepted|Current|Keep separate/.test(t)?'success':/Unavailable|Declined/.test(t)?'danger':'')}">${esc(t)}</span>`;
const note=(txt,cl='info')=>`<div class="callout ${cl}">${icon(cl==='warning'?'alert':'info')}<div>${txt}</div></div>`;
const panel=(title,body,foot='')=>`<section class="panel"><div class="panelhead"><h3>${title}</h3></div><div class="panelbody">${body}</div>${foot?`<div class="panelfoot">${foot}</div>`:''}</section>`;
const tabs=[['queue','Quality queue'],['compare','Record comparison'],['proposal','Correction proposal'],['impact','Impact & relationships'],['review','Review & resolution'],['history','History & follow-up']];
let s,baseRaw=null,role='steward',view='queue',selected='DQ-02',revision=null,query='',family='All findings',status='All open',priority='All priorities',sort='priority',metric='',readMode='Complete',dirty=null,paused='',failedSave=false,busy=false,sourcePanel=null,lastTrigger=null,fullEvidence=null,toastTimer;
function cse(){return s.cases.find(c=>c.id===selected&&M.caseAllowed(s,role,c));}
function proposal(c=cse()){return c?(revision===null?M.latest(c):M.exact(c,revision)):null;}
function fmt(time){return time?new Intl.DateTimeFormat('en-AU',{dateStyle:'medium',timeStyle:'short',timeZone:'Australia/Brisbane'}).format(new Date(time))+' AEST':'Unknown';}
function due(c){if(!c.due)return 'Date needed';const d=c.due.localeCompare('2026-09-17');return (d<0?'Overdue · ':d===0?'Due today · ':'Due ')+new Intl.DateTimeFormat('en-AU',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(c.due+'T00:00:00Z'));}
function age(c){return Math.floor((Date.parse('2026-09-17T02:00:00Z')-Date.parse(c.created))/86400000)+' days open';}
function msg(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4300);}
function modal(title,body,actions){lastTrigger=document.activeElement;$('dialog').innerHTML=`<div class="panelhead"><h2 id="dialog-title">${esc(title)}</h2>${button('close-dialog',icon('close'),'iconbutton','aria-label="Close dialog"')}</div><div class="panelbody"><div id="dialog-error" role="alert"></div>${body}</div><div class="actionbar end">${actions||button('close-dialog','Close')}</div>`;$('dialog').showModal();}
function closeModal(){if($('dialog').open)$('dialog').close();if(lastTrigger?.isConnected)lastTrigger.focus();else $('content').focus({preventScroll:true});}
function showError(e){const target=$('dialog').open?$('dialog-error'):$('form-error');if(target){target.innerHTML=esc(e.message||e);target.className='error-summary';target.tabIndex=-1;target.focus();}else{msg(e.message||e);}}
function allowedCases(){return M.visible(s,role);}
function filtered(){let list=allowedCases().filter(c=>{
 const searchable=[c.id,c.title,c.family,c.domain,c.owner,c.observation,...c.subjects.filter(id=>M.recordAllowed(s,role,id)).flatMap(id=>[id,s.records[id].name,s.records[id].serial]),...c.evidence.map(e=>e.id)].join(' ').toLowerCase();
 return (!query||searchable.includes(query.toLowerCase()))&&(family==='All findings'||c.family===family)&&(priority==='All priorities'||c.priority===priority)&&(status==='All permitted'||status==='All open'&&c.state!=='Closed'||status==='My work'&&c.owner===M.actor(role).name&&c.state!=='Closed'||status===c.state)&&(metric!=='unassigned'||!c.owner&&c.state!=='Closed')&&(metric!=='evidence'||c.state==='Needs information'||c.coverage!=='Current')&&(metric!=='review'||c.state==='Awaiting review')&&(metric!=='domain'||c.state==='Awaiting domain action')&&(metric!=='unknown'||c.outcome==='Outcome unknown');
 });list.sort((a,b)=>sort==='due'?(a.due||'9999').localeCompare(b.due||'9999'):sort==='age'?a.created.localeCompare(b.created):a.priority.localeCompare(b.priority)||a.id.localeCompare(b.id));return list;}
function route(push=true){const h='#'+new URLSearchParams({view,case:selected,rev:revision===null?'latest':String(revision)});if(push)history.pushState(null,'',h);else history.replaceState(null,'',h);try{localStorage.setItem(UIKEY,JSON.stringify({query,family,status,priority,sort,metric,selected,view,revision}));}catch{}}
function navigate(v,id=selected,rev=revision,push=true){const go=()=>{view=v;selected=id;revision=rev;fullEvidence=null;sourcePanel=null;$('drawer').hidden=true;dirty=null;route(push);render();$('content').focus({preventScroll:true});};if(dirty){modal('Unsaved proposal','<p>Your entered fields are still in this tab. Save the draft before leaving, or discard these unsaved changes.</p>',button('stay','Keep editing')+button('discard','Discard changes')+button('save-leave','Save and continue','primary'));App.pendingNav=go;}else go();}
function persist(next){s=next;s.generation++;try{if(failedSave)throw Error('Simulated local write failure.');const current=localStorage.getItem(KEY);if(current!==baseRaw){paused='Another tab has a newer saved state. Your changes are retained in this tab. Export a scoped review copy or reload the saved state.';return false;}const raw=JSON.stringify(s);localStorage.setItem(KEY,raw);baseRaw=raw;paused='';return true;}catch{paused='Local save failed. In-tab changes are retained. Retry this same save before performing another material action.';return false;}}
async function commit(action,data={},id=selected){if(paused)throw Error('Resolve the local save/recovery hold before another change.');if(readMode!=='Complete')throw Error('Restore the complete fixture response before consequential actions.');const n=await M.command(s,role,id,action,data);const saved=persist(n);render();msg(saved?'Saved locally.':'Change retained in this tab; local save needs attention.');return saved;}
function render(){
 const list=allowedCases(),noScope=role==='denied';if(noScope){sourcePanel=null;fullEvidence=null;$('drawer').hidden=true;}
 const counts=[['unassigned','Unassigned',list.filter(c=>!c.owner&&c.state!=='Closed').length],['evidence','Needs evidence',list.filter(c=>c.state==='Needs information'||c.coverage!=='Current').length],['review','Awaiting review',list.filter(c=>c.state==='Awaiting review').length],['domain','Awaiting domain action',list.filter(c=>c.state==='Awaiting domain action').length],['unknown','Outcome unknown',list.filter(c=>c.outcome==='Outcome unknown').length]];
 $('summary').innerHTML=noScope?'':counts.map(([id,label,n])=>`<button class="metric" data-action="metric" data-id="${id}" aria-pressed="${metric===id}"><span>${label}</span><b>${readMode==='Complete'?n:'—'}</b></button>`).join('');
 $('coverage').innerHTML=noScope?'No permitted scope.':icon('info')+`${readMode==='Complete'?list.length+' permitted cases in this fixture response':esc(readMode)+' response · complete totals unavailable'} · Preview date 17 Sep 2026 · AEST`;
 $('banner').innerHTML=paused?note(esc(paused)+`<div class="row mt8">${button('retry-save','Retry same save','smallbutton')}${button('reload-state','Reload saved state','smallbutton')}${button('export','Export review copy','smallbutton')}</div>`,'danger'):'';
 renderToolbar();
 $('tabs').innerHTML=tabs.map(([key,label])=>`<button role="tab" id="tab-${key}" aria-selected="${view===key}" aria-controls="content" tabindex="${view===key?0:-1}" data-action="tab" data-id="${key}">${label}</button>`).join('');$('content').setAttribute('aria-labelledby','tab-'+view);
 $('footer-state').textContent=`${M.actor(role).label} · ${paused?'Save held':'Local session'} · No live connections`;
 if(noScope){$('content').innerHTML=empty('Access unavailable','No permitted case data is displayed or exported. Change the fictional preview role in Preview options.');return;}
 if(fullEvidence){$('content').innerHTML=renderFullEvidence();return;}
 if(view==='queue')$('content').innerHTML=renderQueue();else{const c=cse();$('content').innerHTML=c?renderContext(c)+(view==='compare'?renderCompare(c):view==='proposal'?renderProposal(c):view==='impact'?renderImpact(c):view==='review'?renderReview(c):renderHistory(c)):empty('Exact case unavailable','The selected case is unavailable in this scope. Return to the permitted queue.');}
}
function renderToolbar(){const options=(arr,sel)=>arr.map(x=>`<option ${x===sel?'selected':''}>${esc(x)}</option>`).join('');$('toolbar').innerHTML=`<div class="toolbar"><div class="search">${icon('search')}<input id="search" aria-label="Search permitted cases" placeholder="Search cases, records, serials or sources…" value="${esc(query)}" ${role==='denied'?'disabled':''}></div><select id="status-filter" aria-label="Case view">${options(['All open','All permitted','My work','Needs information','Awaiting review','Awaiting domain action','Closed'],status)}</select><select id="family-filter" aria-label="Finding family">${options(['All findings','Duplicate candidates','Identity & serials','Missing context','Relationships','External mappings','Units & measures','Source coverage'],family)}</select>${button('filters',icon('filter')+'More filters','','aria-label="Priority and sort filters"')}${button('clear','Clear','quiet smallbutton')}</div>${metric?`<div class="row" style="margin-bottom:12px">${button('clear-metric',esc({unassigned:'Unassigned',evidence:'Needs evidence',review:'Awaiting review',domain:'Awaiting domain action',unknown:'Outcome unknown'}[metric])+' ×','active-chip')}</div>`:''}`;}
function empty(title,text){return `<section class="panel empty">${icon('info')}<h2>${esc(title)}</h2><p>${esc(text)}</p>${button('tab','Return to queue','','data-id="queue"')}</section>`;}
function renderQueue(){if(readMode==='Loading')return empty('Loading fixture response','The previous snapshot is retained; counts are unavailable until the response completes. Use Preview options to restore Complete.');if(readMode==='Empty')return empty('No cases in this response','Complete empty demonstration response. This does not clear retained cases or prove a clean data set.');const list=filtered(),c=cse();const warning=readMode!=='Complete'?note(`${esc(readMode)} fixture response. Last successful observation: ${fmt(s.scan.lastSuccess)}. The retained rows below are a prior snapshot; they do not establish current completeness.`,'warning'):'';return warning+`<div class="queue-layout ${warning?'mt':''}"><section class="panel"><div class="panelhead"><div class="row"><h3>Investigation queue</h3>${badge(list.length+' shown')}</div><span class="small">${sort==='due'?'Due date':sort==='age'?'Oldest first':'Priority, then case'}</span></div><div class="case-list">${list.length?list.map(c=>`<article class="case-row ${selected===c.id?'selected':''}"><div><div class="row small"><span class="mono">${esc(c.id)}</span><span>·</span><span>${esc(c.family)}</span></div><button class="case-title" data-action="select" data-id="${c.id}" aria-label="Open ${esc(c.id)} ${esc(c.title)}">${esc(c.title)}</button><div class="context">${M.fullAccess(s,role,c)?esc(s.records[c.target].organisation+' · '+s.sites[c.site].name):'Permitted investigation · counterpart unavailable'}</div><div class="minor"><span>${icon('user')} ${esc(c.owner||'Unassigned')}</span><span>${esc(due(c))}</span><span>${esc(age(c))}</span></div></div><div class="side">${badge(c.state)}${badge(c.priority,c.priority==='High'?'warning':'')}${c.outcome==='Outcome unknown'?badge(c.outcome):c.coverage!=='Current'?badge(c.coverage):''}</div></article>`).join(''):'<div class="empty"><h3>No matching cases</h3><p>Clear or adjust the current filters.</p>'+button('clear','Clear filters')+'</div>'}</div><div class="panelfoot">Scenario labels DQ-01–DQ-16 are demonstration references. No production case numbering is assigned.</div></section><aside class="queue-detail">${c?renderSnapshot(c):panel('Select a case','Choose a permitted row to inspect its next action.')}</aside></div>`;}
function renderSnapshot(c){return `<section class="panel"><div class="panelhead"><h3>Case snapshot</h3>${button('open','Open full detail','smallbutton')}</div><div class="panelbody"><div class="row">${badge(c.id)}${badge(c.coverage)}</div><h2 class="detail-title">${esc(c.title)}</h2><p class="detail-summary">${esc(c.observation)}</p><dl class="facts"><div><dt>Record owner</dt><dd>${esc(c.domain)}</dd></div><div><dt>Case owner</dt><dd>${esc(c.owner||'Unassigned')}</dd></div><div><dt>Due</dt><dd>${esc(due(c))}</dd></div><div><dt>Source basis</dt><dd>Observation v${c.sourceVersion}</dd></div></dl><div class="next-card"><h3>Next meaningful action</h3><p>${esc(c.next)}</p>${button(c.outcome==='Outcome unknown'?'review-next':'open',c.outcome==='Outcome unknown'?'Inspect original outcome':'Investigate case','primary')}</div><div class="row mt">${button('triage','Assign / triage','smallbutton')}${button('export',icon('download')+'Review copy','smallbutton')}</div></div><div class="panelfoot">Review acceptance, record correction and follow-up completion remain separate.</div></section>`;}
function renderContext(c){const p=proposal(c);return `<div class="case-context"><div><div class="row">${button('tab',icon('arrow')+'Queue','quiet smallbutton','data-id="queue"')}<span class="mono">${c.id}</span><span class="small">${esc(c.family)} · ${esc(c.domain)}</span></div><h2>${esc(c.title)}</h2><p class="small">${esc(c.owner||'Unassigned')} · ${esc(due(c))} · ${esc(age(c))}</p></div><div class="row"><select id="revision" class="revision" aria-label="Exact proposal revision"><option value="latest" ${revision===null?'selected':''}>Latest proposal</option>${c.proposals.map(p=>`<option value="${p.rev}" ${revision===p.rev?'selected':''}>Exact r${p.rev} · ${p.status}</option>`).join('')}${revision!==null&&!M.exact(c,revision)?`<option value="${revision}" selected>r${revision} · unavailable</option>`:''}</select>${button('export',icon('download')+'Review copy','smallbutton')}</div></div><div class="statebar"><div><small>Investigation</small>${badge(c.state)}</div><div><small>Selected proposal</small>${badge(p?'r'+p.rev+' · '+p.status:revision!==null?'Exact revision unavailable':'Not started')}</div><div><small>Receiving outcome</small>${badge(c.outcome)}</div><div><small>Evidence</small>${badge(c.coverage)}</div></div><div id="form-error" role="alert"></div>`;}
function sources(c){return c.evidence.map((e,i)=>`<button class="source" data-action="source" data-index="${i}">${icon('file')}<span>${esc(e.title)}<small>${esc(e.id)} · exact v${e.version} · ${e.available?'Available':'Unavailable'}</small></span>${icon('chevron')}</button>`).join('');}
function recordCard(id,index){if(!M.recordAllowed(s,role,id))return panel('Comparison record unavailable',note('Current access to this record is unavailable. No name, serial, site or source details are disclosed.','warning'));const r=s.records[id],site=s.sites[r.site];return `<section class="compare-card"><header><div class="row between"><span class="eyebrow">Record ${index+1}</span>${badge('Version '+r.version)}</div><h3>${esc(r.name)}</h3><div class="mono">${esc(r.id)}</div></header><div class="compare-fields">${[['Organisation',r.organisation],['Site',site.name],['Address',site.address],['Installed at',r.location],['Serves',r.served.join(' · ')],['Manufacturer / model',r.manufacturer+' / '+r.model],['Serial',r.serial===null?'Unknown — not supplied':r.serial]].map(([k,v])=>`<div class="field-row ${k==='Serial'?'highlight':''}"><span>${k}</span><span class="wrap ${k==='Serial'?'mono':''}">${esc(v)}</span></div>`).join('')}</div></section>`;}
function special(c){if(c.kind==='mapping')return panel('Composite ERP identity',`<div class="two">${['AU-DEMO','NZ-DEMO'].map(company=>`<div class="readonly"><strong>${company}</strong><p>MYOB Acumatica · Demo connector<br>Company: ${company}<br>Entity: Customer<br>External key: <code>C0042</code></p></div>`).join('')}</div><p class="footnote mt">These are distinct composite identities. MYOB retains account authority; AD-05 receives the reconciliation request.</p>`);if(c.kind==='unit')return panel('Source representation',`<div class="three"><div><small>Source footprint</small><h2>1.250 ha</h2></div><div><small>Recorded target</small><h2>1.250 m²</h2></div><div><small>Other source semantics</small><p>Unknown: crop area<br>Known zero: 0 m² excluded<br>Not applicable: tank volume</p></div></div><p class="footnote mt">No automatic conversion, precision change or overlapping-area total is applied.</p>`);if(c.kind==='hierarchy')return panel('Invalid facility relationship',`<div class="readonly">SYN-FAC-A → SYN-FAC-B → SYN-FAC-A</div><p class="mt8">The recorded parent chain returns to its starting point. The supported demonstration proposal is the same-site root <code>SYN-FAC-ROOT</code>. A physical relocation belongs to the location lifecycle owner.</p>`);if(c.kind==='site')return panel('Site and billing meanings',`<div class="two"><div><small>Physical work location</small><p>${esc(s.sites.north.address)}</p></div><div><small>Billing account location</small><p>PO Box 100, Exampleville QLD 4000</p></div></div><p class="footnote mt">Site operator: Banksia Demonstration Nurseries. Bill-to: the mapped fictional MYOB account. This request cannot change the account address.</p>`);if(c.kind==='relationship')return panel('Installed location is not a served-area link',`<p><strong>Irrigation shed</strong> — installed equipment location</p><p>Valid served areas: Block A, Block B and Block C.</p><p class="mt8">Review the additional South propagation link separately. No relocation or parent/component change is inferred.</p>`);return '';}
function renderCompare(c){return `<div class="stack">${note(esc(c.observation),c.coverage==='Current'?'info':'warning')}${special(c)}<div class="two">${c.subjects.map(recordCard).join('')}</div><div class="two">${panel('Exact source evidence',M.fullAccess(s,role,c)?sources(c):'<p>Evidence withheld while required comparison access is unavailable.</p>')}${panel('Investigation decision',`<p>${esc(c.next)}</p><p class="footnote mt">A matching label or serial is a comparison signal. It is not a rule to merge canonical records.</p><div class="row mt">${button('tab','Prepare proposal','primary','data-id="proposal"')}${button('clarify','Request information')}</div>`)}</div></div>`;}
function renderProposal(c){if(!M.fullAccess(s,role,c))return empty('Required scope unavailable','Proposal content and actions are withheld.');if(revision!==null&&!proposal(c))return empty('Exact proposal revision unavailable','This reference has not been substituted with the latest revision.');let p=dirty||proposal(c)||M.base(s,c,role);const editable=p.status==='Draft'&&M.can(role,'draft')&&(revision===null||revision===M.latest(c)?.rev);const current=M.latest(c),isOld=current&&p.rev!==current.rev;const supported=c.kind==='serial'?'Equipment serial transcription':c.kind==='keep'?'Reviewed no-change disposition':c.kind==='hierarchy'?'Same-site parent request':'Domain-owner correction request';const fields=`<div class="formgrid"><div><label>Correction type</label><div class="readonly">${esc(supported)}</div></div><div><label>Target basis</label><div class="readonly">${esc(p.target)} · expected v${p.expectedVersion}</div></div><div><label>Before value</label><div class="readonly mono">${esc(c.kind==='serial'?(p.before===null?'Unknown — not supplied':p.before):'Retained source observation v'+p.sourceVersion)}</div></div><label><span>${c.kind==='serial'?'Proposed exact serial':c.kind==='keep'?'Disposition':'Exact proposed owner request'}</span>${c.kind==='keep'?`<select id="proposal-after" ${!editable?'disabled':''}><option>Keep separate</option></select>`:`<input id="proposal-after" value="${esc(p.after)}" ${!editable?'readonly':''} placeholder="${c.kind==='serial'?'Preserve leading zeros and case':c.kind==='hierarchy'?'SYN-FAC-ROOT':'Describe the bounded owner action'}">`}</label><label class="full"><span>Rationale and source interpretation</span><textarea id="proposal-rationale" ${!editable?'readonly':''}>${esc(p.rationale)}</textarea></label><div class="full"><label>Evidence included in this proposal</label>${c.evidence.map(e=>`<label class="check"><input type="checkbox" class="proposal-evidence" value="${esc(e.id+'@'+e.version)}" ${p.evidence.includes(e.id+'@'+e.version)?'checked':''} ${!editable||!e.available?'disabled':''}><span>${esc(e.title)} · ${esc(e.id)} v${e.version}${!e.available?' · Unavailable':''}</span></label>`).join('')}</div>${c.findings.length?`<div class="full">${c.findings.map(f=>note('Retained finding '+esc(f.id)+': '+esc(f.reason),'warning')).join('')}</div><label class="full"><span>Response to retained blocking findings</span><textarea id="proposal-response" ${!editable?'readonly':''}>${esc(p.response)}</textarea></label>`:''}<label class="check full"><input type="checkbox" id="proposal-impact" ${p.impactAcknowledged?'checked':''} ${!editable?'disabled':''}><span>I reviewed the current target, draft dependencies and retained issued/historical references. Only the bounded owner action is proposed.</span></label></div>`;return `<div class="two"><section class="panel"><div class="panelhead"><h3>${p.status==='Draft'?'Correction draft':'Frozen proposal'} · r${p.rev}</h3>${badge(p.status)}</div><div class="panelbody">${isOld?note('You are inspecting an earlier exact revision. Current actions remain with the latest proposal.','warning'):''}${fields}</div><div class="actionbar"><span class="save-state" id="draft-state">${dirty?'Unsaved changes':p.status==='Draft'?'Draft can be saved incomplete':'Exact content retained'}</span>${editable?button('save','Save draft')+button('submit','Submit for review','primary'):M.can(role,'draft')&&!isOld&&c.outcome!=='Applied'&&['Returned','Declined','Accepted'].includes(p.status)?button('successor','Create corrected successor','primary'):''}</div></section><div class="stack">${panel('Correction boundary',`<p>${c.kind==='serial'?'This fictional policy permits one current serial transcription correction through the local Equipment simulator.':'The receiving domain owns the actual record change. This workspace prepares a reviewed request.'}</p><p class="footnote mt">Blank serials, arbitrary fields, asset replacement and physical moves are not supported as transcription corrections.</p>${button('tab','Review affected references','smallbutton mt','data-id="impact"')}`)}${panel(c.outcome==='Applied'?'Retained correction result':'Readiness',c.outcome==='Applied'?'<p>This proposal has a retained simulated receiving result. Its expected pre-correction version remains part of the original evidence; inspect Review & resolution for the resulting version.</p>':`<ul class="checklist">${M.ready(s,c,p,role).length?M.ready(s,c,p,role).map(x=>'<li>'+esc(x)+'</li>').join(''):'<li>Required fixture basis is present. Independent review is still required.</li>'}</ul>`)}${p.predecessor?panel('Successor comparison',renderDiff(c,p)):''}${p.digest?panel('Content identity',`<p class="mono">SHA-256 ${p.digest}</p><p class="footnote mt">Identifies submitted content; it does not prove source truth or protect this local file from modification.</p>`):''}</div></div>`;}
function renderDiff(c,p){const before=M.exact(c,p.predecessor);if(!before)return 'Predecessor unavailable.';const keys=['after','rationale','evidence','expectedVersion','sourceVersion','impactVersion','policy','response'];return keys.filter(k=>M.canonical(before[k])!==M.canonical(p[k])).map(k=>`<div class="field-row"><span>${esc(k)}</span><div><small>r${before.rev}</small><p class="wrap">${esc(Array.isArray(before[k])?before[k].join(', '):before[k])}</p><small>r${p.rev}</small><p class="wrap">${esc(Array.isArray(p[k])?p[k].join(', '):p[k])}</p></div></div>`).join('')||'<p>No material field changes yet; current basis is captured separately.</p>';}
const impacts=[['Current master','One supported current field may change. Stable equipment identity and relationships stay retained.','Owner correction','user'],['Draft preparation','Draft visit SYN-VISIT-014 may display the old serial. Prepare a Service-owned reassessment.','Follow-up needed','calendar'],['Approved scope','Original approved scope and technical decisions keep their exact basis. New use requires review.','Retain snapshot','check'],['Issued job pack','SYN-PACK-014 v1 and SYN-ACK-014 remain unchanged. Current corrections do not rewrite issued content.','Retain issued bytes','file'],['Historical service','Event-time site, configuration and response context remain attributable to the original event.','Retain event context','clock'],['External mapping','MYOB provider, company, entity and key remain authoritative. No posting or source-master write occurs.','Separate owner','link']];
function renderImpact(c){if(!M.fullAccess(s,role,c))return empty('Impact evidence unavailable','Required subject scope is unavailable.');const issued=c.target==='SYN-EQP-101'?s.issued:s.issuedByTarget[c.target];return `<div class="stack">${note(`Impact observation v${c.impactVersion} · ${c.impactComplete?'Complete within the declared synthetic reference set.':'Partial; required dependency evidence is missing.'}`,c.impactComplete?'info':'warning')}<section class="panel"><div class="panelhead"><h3>How each reference is treated</h3>${badge('6 reference categories')}</div>${impacts.map(([a,b,t,i])=>`<div class="impact-row"><div class="impact-icon">${icon(i)}</div><div><h3>${a}</h3><p>${esc(b.replaceAll('SYN-PACK-014',issued.id).replaceAll('SYN-ACK-014',issued.acknowledgement.id))}</p></div><div>${badge(t)}</div></div>`).join('')}</section><div class="two">${panel('Retained issue and acknowledgement',`<p><strong>${issued.id} · exact v${issued.version}</strong></p><p class="footnote mt8">${esc(issued.bytes)}</p><p class="footnote mt8">Acknowledgement ${issued.acknowledgement.id} · ${fmt(issued.acknowledgement.time)}</p><details class="mt"><summary>Content identities</summary><div class="inside mono">Issue SHA-256: ${issued.hash}<br>Acknowledgement SHA-256: ${issued.ackHash}</div></details>`)}${panel('Owned current-use review',`<p>Prepare the draft-visit review before closing an applied correction. The task remains prepared in this file until a real receiving system returns evidence.</p><div class="row mt">${button('draft-followup','Prepare Service follow-up','primary')}${button('tab','Open history','smallbutton','data-id="history"')}</div>`)}</div></div>`;}
function renderReview(c){if(!M.fullAccess(s,role,c))return empty('Review unavailable','Required counterpart access is unavailable; review and receiver actions are held.');const p=proposal(c);if(!p)return empty(revision===null?'No submitted proposal':'Exact revision unavailable',revision===null?'Prepare, save and submit a proposal to start independent review.':'This reference has not been replaced by the latest proposal.');const current=p.rev===M.latest(c)?.rev;const ready=M.ready(s,c,p,role),op=c.operations.at(-1),receipt=op&&s.ledger[op.id]?.observed?s.ledger[op.id].result:null;
return `<div class="stack"><div class="two">${panel('Exact proposal for review',`<div class="row">${badge('r'+p.rev)}${badge(p.status)}${badge(p.kind)}</div><div class="field-row"><span>Target</span><span>${esc(p.target)} · expected v${p.expectedVersion}</span></div><div class="field-row"><span>Proposed value</span><span class="mono">${esc(p.after)}</span></div><div class="field-row"><span>Author</span><span>${esc(p.author)}</span></div><div class="field-row"><span>Rationale</span><span>${esc(p.rationale||'Not supplied')}</span></div><div class="field-row"><span>Source basis</span><span>${p.evidence.map(esc).join('<br>')}</span></div>${p.response?`<div class="field-row"><span>Author response</span><span>${esc(p.response)}</span></div>`:''}<div class="row mt">${button('tab','Inspect exact proposal','smallbutton','data-id="proposal"')}</div>`)}${panel('Independent review',`<p class="footnote">Preview reviewer: Jordan Lee. The author cannot accept their own work. Every decision retains its exact proposal digest.</p>${c.findings.length?c.findings.map(f=>`<div class="mt">${badge(f.id,'warning')}<p class="small mt8">${esc(f.reason)}</p><p class="small">${f.acceptances.some(a=>a.digest===p.digest)?'Response accepted for this exact revision.':'Response acceptance still required for this revision.'}</p></div>`).join(''):''}${current&&p.status==='Submitted'?`<div class="row mt">${button('decision','Accept exact proposal','primary','data-decision="accept"')}${button('decision','Return','', 'data-decision="return"')}${button('decision','Request information','','data-decision="request"')}${button('decision','Decline','quiet danger','data-decision="decline"')}</div>`:`<div class="mt">${note(current?'Review controls become available for a submitted revision.':'Historical revision: decisions retained; new actions use the latest proposal.')}</div>`}${!M.can(role,'review')?'<p class="footnote mt">Switch to Independent reviewer in Preview options to perform the fictional review.</p>':''}`)}</div>${panel('Receiving result and closure',`<div class="row">${badge(c.outcome)}<span class="small">${c.domain} retains record ownership.</span></div>${p.kind==='keep'?'<p class="mt">A reviewed Keep separate decision requires no record mutation. Verify the evidence and close the investigation as a no-change outcome.</p>':p.kind==='serial'?'<p class="mt">Only the mock Equipment receiver can apply this bounded serial correction. Review acceptance alone does not apply it.</p>':'<p class="mt">This correction requires the receiving owner. An exact request can be prepared locally; no connected send, merge or ERP update is available.</p>'}${c.outcome==='Outcome unknown'?`<div class="mt">${note('The original operation has an uncertain observed outcome. A second equivalent correction is held. Inspect the original result.','warning')}</div>`:''}${ready.length&&c.outcome!=='Applied'?`<details class="mt" open><summary>Current readiness holds (${ready.length})</summary><div class="inside"><ul class="checklist">${ready.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul></div></details>`:''}${receipt?`<div class="mt">${note(`Simulated receipt ${esc(receipt.id)} · ${esc(receipt.before.serial??'Unknown')} → ${esc(receipt.after.serial)} · v${receipt.before.version} → v${receipt.after.version}.`,'success')}</div>`:''}${op?`<details class="mt"><summary>Original operation evidence</summary><div class="inside mono">Operation ${esc(op.id)}<br>Payload digest ${esc(op.digest)}<br>Observed status ${esc(op.status)}${receipt?'<br>Receiving time '+fmt(receipt.time):''}</div></details>`:''}<div class="row mt">${current&&p.status==='Accepted'?(p.kind==='serial'?c.outcome==='Outcome unknown'?button('reconcile','Look up original result','primary'):op?.status==='Confirmed not applied'?button('retry-operation','Retry original operation','primary'):c.outcome==='Applied'?'':button('apply','Apply in Equipment simulator','primary'):p.kind==='keep'?'':button('handover','Prepare owner request','primary')):''}${current&&p.status==='Accepted'&&['Not required','Applied'].includes(c.outcome)&&c.state!=='Closed'?button('close-case','Verify and close case'):''}${button('draft-followup','Prepare Service follow-up','smallbutton')}${button('options','Preview role / interruption','quiet smallbutton')}</div>`)}${panel('Decision record',c.decisions.filter(d=>d.rev===p.rev).map(d=>`<div class="field-row"><span>${esc(d.action)} · r${d.rev}</span><span>${esc(d.reason)}<br><small>${esc(d.reviewer)} · ${fmt(d.time)}</small></span></div>`).join('')||'<p class="muted">No decision for this exact revision.</p>')}</div>`;}
function renderHistory(c){if(!M.fullAccess(s,role,c))return empty('History details withheld','Current access to all referenced subjects is required.');const notes=c.privateNotes[M.actor(role).name]||'';return `<div class="two"><div class="stack">${panel('Case timeline',`<ol class="timeline">${c.events.filter(e=>e.action!=='Private annotation saved'||e.actor===M.actor(role).name).slice().reverse().map(e=>`<li><small>${fmt(e.time)} · ${esc(e.actor)}</small><h3>${esc(e.action)}</h3><p>${esc(e.detail)}</p></li>`).join('')}</ol>`)}${panel('Retained proposal revisions',`<div class="revision-list">${c.proposals.map(p=>button('exact','r'+p.rev+' · '+esc(p.status),'smallbutton',`data-rev="${p.rev}"`)).join('')||'<p>No revisions yet.</p>'}</div>`)}</div><div class="stack">${panel('Prepared receiving work',c.followups.length?c.followups.map(f=>`<article class="mt"><div class="row between"><h3>${esc(f.kind)}</h3>${badge(f.status)}</div><p class="small mt8">${esc(f.id)} · ${esc(f.domain)}</p><p class="mt8">${esc(f.reason)}</p><p class="small mt8">${esc(f.owner)} · ${f.due?'Due '+esc(f.due):'Date needed'}</p></article>`).join(''):'<p class="muted">No receiving work prepared. A local request does not imply delivery or completion.</p>')}${M.can(role,'draft')?panel('Private working note',`<p class="footnote">Visible to this fictional author in the preview. Excluded from review copies and proposal digests.</p><label class="mt"><span>Working note</span><textarea id="private-note">${esc(notes)}</textarea></label><div class="row mt">${button('save-note','Save private note')}</div>`):''}${panel('New source observation',`<p>Rechecking the same original observation reuses this case. A materially changed source can reopen a closed finding while retaining its earlier decision.</p><div class="row mt">${button('repeat-observation','Repeat same observation','smallbutton')}${button('new-observation','Simulate new evidence','smallbutton')}</div>`)}</div></div>`;}
function openSource(index){const c=cse();if(!c||!M.fullAccess(s,role,c))return showError('Evidence unavailable.');const e=c.evidence[index];if(!e)return;lastTrigger=document.activeElement;sourcePanel={case:c.id,index};$('drawer').innerHTML=`<div class="panelhead"><h3>Evidence snapshot</h3>${button('close-panel',icon('close'),'iconbutton','aria-label="Close evidence snapshot"')}</div><div class="panelbody"><div class="row">${badge('Exact v'+e.version)}${badge(e.available?'Available':'Unavailable')}</div><h2 class="mt">${esc(e.title)}</h2><p class="mono mt8">${esc(e.id)}</p><dl class="facts"><div><dt>Owner</dt><dd>${esc(e.owner)}</dd></div><div><dt>Observed at</dt><dd>${fmt(e.asAt)}</dd></div></dl>${e.available?note(esc(e.text)):note('The exact source is unavailable. The current version has not been substituted.','warning')}<p class="footnote mt">Synthetic retained text, not an uploaded photograph or live document.</p></div><div class="actionbar">${button('full-source','Open full detail','primary')}${button('close-panel','Close')}</div>`;$('drawer').hidden=false;$('drawer').focus();}
function renderFullEvidence(){const c=cse(),e=c&&M.fullAccess(s,role,c)?c.evidence[fullEvidence.index]:null;if(!e)return empty('Exact evidence unavailable','No latest-version substitution has been made.');return button('back-source',icon('arrow')+'Back to comparison','quiet')+panel(esc(e.title),`<p class="mono">${esc(e.id)} · exact v${e.version}</p><p class="small mt8">${esc(e.owner)} · ${fmt(e.asAt)}</p><div class="mt">${e.available?esc(e.text):note('Exact source unavailable.','warning')}</div><p class="footnote mt">All content is fictional. The source excerpt remains bound to this exact version.</p>`);}
function collectDraft(){const c=cse(),p=M.clone(dirty||proposal(c)||M.base(s,c,role));p.after=$('proposal-after')?.value??p.after;p.rationale=$('proposal-rationale')?.value??p.rationale;p.evidence=[...document.querySelectorAll('.proposal-evidence:checked')].map(x=>x.value);p.impactAcknowledged=$('proposal-impact')?.checked??p.impactAcknowledged;p.response=$('proposal-response')?.value??p.response;if(c.kind==='keep')p.disposition='Keep separate';if(c.id==='DQ-02')p.disposition='Keep separate';return p;}
async function saveDraft(){const d=collectDraft();await commit('save',d);dirty=null;revision=null;render();}
function exportCopy(){const c=cse();if(!c)throw Error('Select a permitted case first.');const copy=M.reviewCopy(s,role,c.id,revision);if(dirty)copy.unsavedDraft=M.clone(dirty);download(c.id+'-review-copy.json',JSON.stringify(copy,null,2),'application/json');msg('Scoped review copy downloaded. Private notes excluded.');}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function options(){modal('Preview options',`<p class="footnote">Synthetic controls demonstrate roles and failure states. All fixtures are inspectable in this HTML; role selection is not authentication.</p><div class="formgrid mt"><label><span>Fictional actor</span><select id="option-role">${Object.entries(M.roles).map(([k,v])=>`<option value="${k}" ${role===k?'selected':''}>${esc(v.label)} · ${esc(v.name)}</option>`).join('')}</select></label><label><span>Fixture read state</span><select id="option-read">${['Complete','Partial','Failed','Loading','Empty'].map(x=>`<option ${readMode===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span>Next receiver response</span><select id="option-receiver">${['Normal','Response lost','Still unknown','Confirmed not applied'].map(x=>`<option ${App.receiverMode===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="check"><input type="checkbox" id="option-save" ${failedSave?'checked':''}><span>Simulate failed local write</span></label></div><details class="mt"><summary>Evidence and local-state scenarios</summary><div class="inside"><p class="footnote">Changes affect only this fictional workspace. Reset replaces all demo cases, decisions and mock operations.</p><div class="row mt">${button('change-target','Change target version','smallbutton')}${button('change-source','Change source version','smallbutton')}${button('change-policy','Change policy version','smallbutton')}${button('partial-impact','Toggle partial impact','smallbutton')}${button('stale-tab','Simulate stale save','smallbutton')}${button('corrupt-state','Simulate damaged saved state','smallbutton danger')}</div></div></details>`,button('reset','Reset demonstration','danger')+button('close-dialog','Cancel')+button('apply-options','Apply preview options','primary'));}
function help(){modal('About this workbench',`<div class="stack"><p>AD-03 r01 covers investigation, exact proposals, independent review and record-owner resolution. The preview clock starts on 17 September 2026 (AEST).</p><div>${[['1','Open DQ-02','Compare the two pumps and inspect both exact sources.'],['2','Prepare the correction','Enter 00-EP-101, explain the evidence and acknowledge impacts; save and submit.'],['3','Review independently','Choose Independent reviewer in Preview options. Return with a reason, then let the steward create r02 and respond.'],['4','Accept the exact response','Re-submit r02; the reviewer accepts its response and proposal.'],['5','Apply and recover','Choose Equipment operator. Select Response lost to demonstrate original-result recovery.'],['6','Close with follow-up','Prepare the Service draft review; switch to Data steward and verify closure.']].map(([n,t,d])=>`<div class="step"><b>${n}</b><div><strong>${t}</strong><p class="small">${d}</p></div></div>`).join('')}</div>${note('DQ-11 starts with a changed target after acceptance. DQ-13 starts with a lost correction response. Other fixtures demonstrate owner requests and evidence holds.')}<p class="footnote">Self-contained HTML. Local browser storage only. No MYOB, SharePoint, email or PPO API connection. All names, addresses and records are fictional. Browser storage is not a durable multi-user transaction system.</p><p class="footnote">Theme: PPO board r22; r20 workspace composition lineage. Embedded Roboto and line icons retain the source design provenance. See the companion report for verification and receiving requirements.</p></div>`);}
function reasonDialog(title,action,extra=''){modal(title,`${extra}<label class="mt"><span>Reason / verification evidence</span><textarea id="reason" required placeholder="Explain the exact decision and evidence…"></textarea></label>`,button('close-dialog','Cancel')+button('confirm-reason',title,'primary',`data-command="${action}"`));}
async function scan(){if(paused)throw Error('Resolve the save hold before checking fixtures.');if(!M.can(role,'triage'))throw Error('The data-steward role is required.');const next=M.clone(s);next.scan.run++;next.scan.mode=readMode;if(readMode==='Complete')next.scan.lastSuccess=next.clock;const permitted=M.visible(next,role);const results=M.checkFixtures(next,role);persist(next);render();modal('Fixture check result',`${note(readMode==='Complete'?'Complete within the declared permitted fixture set. Rule observations are deterministic; a finding is not proof of a duplicate.':esc(readMode)+' read: retained findings are not a verified all-clear.',readMode==='Complete'?'info':'warning')}<p class="small mt">Run ${s.scan.run} · ${fmt(s.clock)} · ${readMode==='Complete'?permitted.length+' case observations examined':'Examination count unavailable'} · same origin identities reuse the existing cases.</p><div class="mt">${results.map(r=>`<div class="field-row"><span>${r.case}<br>${r.rule}</span><span>${esc(r.result)}</span></div>`).join('')}</div>`);}
async function captureFinding(){const subject=$('capture-target').value;if(!M.recordAllowed(s,role,subject))throw Error('Subject unavailable.');const text=$('capture-observation').value.trim(),origin=$('capture-origin').value.trim();if(!text||!origin)throw Error('An observation and exact origin reference are required.');if(paused)throw Error('Resolve the local save hold first.');if(!M.can(role,'triage'))throw Error('Data-steward role required.');const exists=s.cases.find(c=>c.origin===origin&&c.target===subject);if(exists){selected=exists.id;closeModal();render();msg('Existing original finding reopened in the workbench; no duplicate case created.');return;}
 const n=M.clone(s),r=n.records[subject],id='DQ-'+String(n.cases.length+1).padStart(2,'0'),template=M.clone(n.cases[3]);Object.assign(template,{id,title:$('capture-title').value.trim()||'Manually captured identity finding',target:subject,subjects:[subject],site:r.site,observation:text,origin,owner:$('capture-owner').value.trim()||null,due:$('capture-due').value||null,created:n.clock,evidence:[{id:origin,version:1,title:'Manual observation · unversioned source',owner:'Data steward',asAt:n.clock,text,available:true}],coverage:'Current',state:'Investigating',events:[],proposals:[],findings:[],decisions:[],followups:[],operations:[],privateNotes:{}});M.event(n,template,role,'Manual finding captured',text);n.cases.push(template);persist(n);selected=id;revision=null;closeModal();view='compare';route();render();}
async function action(name,el){const c=cse();
if(dirty&&['metric','clear','clear-metric','filters','capture','scan','triage'].includes(name))throw Error('Save or discard your proposal edits before changing the worklist.');
if(name==='tab'){navigate(el.dataset.id);return;}if(name==='select'){navigate(innerWidth<=850?'compare':'queue',el.dataset.id,null);return;}if(name==='open'){navigate('compare',selected,null);return;}if(name==='review-next'){navigate('review',selected,null);return;}if(name==='exact'){navigate('proposal',selected,Number(el.dataset.rev));return;}if(name==='metric'){metric=metric===el.dataset.id?'':el.dataset.id;status='All permitted';view='queue';route();render();return;}
if(name==='clear'||name==='clear-metric'){if(name==='clear'){query='';family='All findings';priority='All priorities';status='All open';}metric='';route();render();return;}
if(name==='filters'){modal('Additional filters',`<div class="formgrid"><label><span>Priority</span><select id="filter-priority">${['All priorities','High','Normal'].map(x=>`<option ${priority===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span>Sort</span><select id="filter-sort">${[['priority','Priority, then case'],['due','Due date'],['age','Oldest first']].map(([k,v])=>`<option value="${k}" ${sort===k?'selected':''}>${v}</option>`).join('')}</select></label></div>`,button('close-dialog','Cancel')+button('apply-filters','Apply filters','primary'));return;}
if(name==='apply-filters'){priority=$('filter-priority').value;sort=$('filter-sort').value;closeModal();route();render();return;}
if(name==='help'){help();return;}if(name==='options'){if(dirty){showError('Save or discard your proposal edits before changing preview settings.');return;}options();return;}if(name==='close-dialog'||name==='stay'){closeModal();return;}if(name==='discard'){closeModal();App.pendingNav?.();return;}if(name==='save-leave'){await saveDraft();closeModal();App.pendingNav?.();return;}
if(name==='apply-options'){role=$('option-role').value;readMode=$('option-read').value;failedSave=$('option-save').checked;App.receiverMode=$('option-receiver').value;closeModal();sourcePanel=null;fullEvidence=null;$('drawer').hidden=true;const allowed=allowedCases();if(!allowed.some(x=>x.id===selected)){selected=allowed[0]?.id||'';revision=null;view='queue';}render();return;}
if(name==='source'){openSource(Number(el.dataset.index));return;}if(name==='close-panel'){sourcePanel=null;$('drawer').hidden=true;if(lastTrigger?.isConnected)lastTrigger.focus();else $('content').focus();return;}if(name==='full-source'){fullEvidence=sourcePanel;$('drawer').hidden=true;render();$('content').focus();return;}if(name==='back-source'){fullEvidence=null;render();return;}
if(name==='save'){await saveDraft();return;}if(name==='submit'){await saveDraft();await commit('submit');navigate('review',selected,null);return;}if(name==='successor'){await commit('successor');revision=null;render();return;}if(name==='decision'){reasonDialog({accept:'Accept exact proposal',return:'Return for correction',request:'Request information',decline:'Decline proposal'}[el.dataset.decision],el.dataset.decision,c.findings.length&&el.dataset.decision==='accept'?'<label class="check"><input type="checkbox" id="accept-response"><span>I accept the response to every blocking finding against this exact corrected proposal.</span></label>':'');return;}
if(name==='confirm-reason'){await commit(el.dataset.command,{reason:$('reason').value,acceptResponse:$('accept-response')?.checked});closeModal();render();return;}
if(name==='apply'){modal('Apply in the Equipment simulator',`<p>This changes one fictional current serial through the mock record owner. It retains the original value, both identities and historical issued content.</p><p class="small mt">Receiver scenario: ${esc(App.receiverMode)}</p>`,button('close-dialog','Cancel')+button('confirm-apply','Apply simulated correction','primary'));return;}
if(name==='confirm-apply'){await commit('apply',{loseResponse:App.receiverMode==='Response lost',mode:App.receiverMode==='Still unknown'?'unknown':App.receiverMode==='Confirmed not applied'?'not-applied':'normal'});closeModal();render();return;}
if(name==='reconcile'){await commit('reconcile');return;}if(name==='retry-operation'){await commit('retry');return;}if(name==='close-case'){reasonDialog('Verify and close case','close','<p>Verify the exact current value or accepted no-change basis. Prepared follow-ups remain independently owned and open.</p>');return;}
if(name==='handover'||name==='draft-followup'||name==='clarify'){modal(name==='handover'?'Prepare owner request':name==='draft-followup'?'Prepare Service follow-up':'Prepare evidence clarification',`<p class="footnote">This creates a local receiving request only. No message is sent.</p><div class="formgrid mt"><label><span>Receiving owner</span><input id="follow-owner" value="${name==='draft-followup'?'Service preparation owner':esc((c?.domain||'Domain')+' owner')}"></label><label><span>Due date (or Date needed)</span><input id="follow-due" type="date"></label><label class="full"><span>Reason / required work</span><textarea id="follow-reason">${esc(name==='draft-followup'?'Review the draft visit against the corrected current serial; preserve the issued pack and acknowledgement.':c?.next||'Clarify the exact source evidence.')}</textarea></label></div>`,button('close-dialog','Cancel')+button('confirm-follow','Prepare locally','primary',`data-command="${name}"`));return;}
if(name==='confirm-follow'){await commit(el.dataset.command==='handover'?'handover':'followup',{owner:$('follow-owner').value,due:$('follow-due').value,reason:$('follow-reason').value,purpose:el.dataset.command==='draft-followup'?'draft':'evidence'});closeModal();render();return;}
if(name==='triage'){modal('Assign and triage',`<div class="formgrid"><label><span>Case owner</span><input id="triage-owner" value="${esc(c.owner||'')}"></label><label><span>Due date</span><input id="triage-due" type="date" value="${esc(c.due||'')}"></label><label><span>Priority</span><select id="triage-priority"><option ${c.priority==='High'?'selected':''}>High</option><option ${c.priority==='Normal'?'selected':''}>Normal</option></select></label><label><span>Investigation</span><select id="triage-state"><option>Assigned</option><option>Investigating</option><option>Needs information</option></select></label><label class="full"><span>Reason for change</span><textarea id="triage-reason"></textarea></label></div>`,button('close-dialog','Cancel')+button('confirm-triage','Save triage','primary'));return;}
if(name==='confirm-triage'){await commit('triage',{owner:$('triage-owner').value,due:$('triage-due').value,priority:$('triage-priority').value,state:$('triage-state').value,reason:$('triage-reason').value});closeModal();render();return;}
if(name==='save-note'){await commit('note',{note:$('private-note').value});return;}if(name==='export'){exportCopy();return;}if(name==='scan'){await scan();return;}
if(name==='capture'){if(!M.can(role,'triage'))throw Error('Data-steward role required.');modal('Capture an identity finding',`<p class="footnote">Capture evidence against a permitted stable equipment record. The same origin and subject reuse the existing finding.</p><div class="formgrid mt"><label class="full"><span>Finding title</span><input id="capture-title"></label><label class="full"><span>Subject record</span><select id="capture-target">${Object.values(s.records).filter(r=>M.recordAllowed(s,role,r.id)).map(r=>`<option value="${r.id}">${r.id} · ${esc(r.name)}</option>`).join('')}</select></label><label class="full"><span>Exact source / origin reference</span><input id="capture-origin" placeholder="Fictional observation reference"></label><label class="full"><span>Observation</span><textarea id="capture-observation"></textarea></label><label><span>Owner</span><input id="capture-owner" value="${esc(M.actor(role).name)}"></label><label><span>Due date (or Date needed)</span><input id="capture-due" type="date"></label></div>`,button('close-dialog','Cancel')+button('confirm-capture','Capture locally','primary'));return;}if(name==='confirm-capture'){await captureFinding();return;}
if(name==='retry-save'){if(!paused)return;failedSave=false;try{const current=localStorage.getItem(KEY);if(current!==baseRaw)throw Error('Saved state differs. Export this tab’s permitted review and deliberately reload; do not overwrite another tab.');const raw=JSON.stringify(s);localStorage.setItem(KEY,raw);baseRaw=raw;paused='';render();msg('The retained state was saved; no business command repeated.');}catch(e){showError(e);}return;}
if(name==='reload-state'){modal('Reload saved state','<p>Any changes held only in this tab will be discarded. Export a scoped review copy first if they are needed.</p>',button('close-dialog','Cancel')+button('confirm-reload','Reload saved state','primary'));return;}if(name==='confirm-reload'){location.reload();return;}
if(['change-target','change-source','change-policy','partial-impact','new-observation','repeat-observation'].includes(name)){if(!M.can(role,'triage')&&!M.can(role,'apply'))throw Error('A steward or operator preview role is required.');if(paused)throw Error('Resolve the save hold first.');if(!c||!M.fullAccess(s,role,c))throw Error('Required scope is unavailable.');if(c.operations.some(o=>o.status==='Outcome unknown')&&name!=='change-source')throw Error('Reconcile the original outcome before changing this scenario.');const n=M.clone(s),nc=M.find(n,c.id);if(name==='change-target')n.records[nc.target].version++;if(name==='change-source'||name==='new-observation'){nc.sourceVersion++;if(name==='new-observation'&&nc.state==='Closed')nc.state='Investigating';}if(name==='change-policy')nc.policy=nc.policy?nc.policy+1:2;if(name==='partial-impact'){nc.impactComplete=!nc.impactComplete;nc.impactVersion++;}M.event(n,nc,role,name==='repeat-observation'?'Original observation reused':'Preview evidence changed',name==='repeat-observation'?'Same origin; no new case or obligation.':name+'; earlier versions and decisions retained.');persist(n);if($('dialog').open)closeModal();render();msg('Fictional scenario updated.');return;}
if(name==='stale-tab'){const n=M.clone(s);n.generation++;localStorage.setItem(KEY,JSON.stringify(n));paused='Simulated newer saved state. Your current in-tab state is retained; reload requires a deliberate choice.';closeModal();render();return;}
if(name==='corrupt-state'){modal('Simulate damaged saved state','<p>This writes an intentionally damaged synthetic envelope and reloads. The next load will retain the raw bytes and pause writes; a deliberate demo reset is available.</p>',button('close-dialog','Cancel')+button('confirm-corrupt','Run damaged-state scenario','danger'));return;}if(name==='confirm-corrupt'){localStorage.setItem(KEY,'{"schema":999,"syntheticDamagedState":true}');location.reload();return;}
if(name==='reset'){modal('Reset the fictional demonstration','<p>This replaces every local demo draft, decision, note and simulated operation, including unknown results. It is a demonstration reset, not a way to recover a real operation.</p>',button('close-dialog','Cancel')+button('confirm-reset','Reset all demo data','danger'));return;}if(name==='confirm-reset'){localStorage.removeItem(KEY);localStorage.removeItem(UIKEY);history.replaceState(null,'','#');location.reload();return;}
}
function validEnvelope(x){return !!x&&x.schema===1&&Number.isInteger(x.generation)&&Array.isArray(x.cases)&&x.cases.length>=16&&x.cases.every(c=>typeof c.id==='string'&&Array.isArray(c.proposals)&&Array.isArray(c.events)&&Array.isArray(c.subjects)&&Array.isArray(c.evidence))&&x.records&&x.sites&&x.ledger&&x.issued&&x.issuedByTarget&&x.scan&&typeof x.clock==='string';}
async function init(){const seed=JSON.parse($('fixtures').textContent);s=await M.initialise(seed);try{baseRaw=localStorage.getItem(KEY);if(baseRaw){const parsed=JSON.parse(baseRaw);if(!validEnvelope(parsed))throw Error('Unsupported or damaged saved state.');s=parsed;}else{const raw=JSON.stringify(s);localStorage.setItem(KEY,raw);baseRaw=raw;}}catch{paused='Saved state is unavailable, damaged or unsupported. Original raw saved bytes are retained; writes are paused. Review the initial fixture view or deliberately reset the demo.';}
 try{const prefs=JSON.parse(localStorage.getItem(UIKEY)||'null');if(prefs){({query='',family='All findings',status='All open',priority='All priorities',sort='priority',metric='',selected='DQ-02',view='queue',revision=null}=prefs);}}catch{}
 readRoute();render();
 document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||busy)return;busy=true;try{await action(el.dataset.action,el);}catch(err){showError(err);}finally{busy=false;}});
 document.addEventListener('input',e=>{if(e.target.id==='search'){if(dirty){e.target.value=query;showError('Save or discard your proposal edits before searching.');return;}query=e.target.value;const focus=e.target.selectionStart;view='queue';route();render();$('search').focus();$('search').setSelectionRange(focus,focus);}else if(e.target.id?.startsWith('proposal-')||e.target.classList.contains('proposal-evidence')){dirty=collectDraft();if($('draft-state'))$('draft-state').textContent='Unsaved changes';}});
 document.addEventListener('change',e=>{if(dirty&&['status-filter','family-filter'].includes(e.target.id)){e.target.value=e.target.id==='status-filter'?status:family;showError('Save or discard your proposal edits before filtering.');return;}if(e.target.id==='status-filter'){status=e.target.value;view='queue';route();render();}if(e.target.id==='family-filter'){family=e.target.value;view='queue';route();render();}if(e.target.id==='revision')navigate(view,selected,e.target.value==='latest'?null:Number(e.target.value));});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('dialog').open&&!$('drawer').hidden){e.preventDefault();action('close-panel',{});}if(e.target.matches('[role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const all=[...document.querySelectorAll('[role=tab]')],i=all.indexOf(e.target),idx=e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowRight'?1:-1)+all.length)%all.length;navigate(tabs[idx][0]);all[idx]?.focus();document.getElementById('tab-'+tabs[idx][0]).focus();}});
 $('dialog').addEventListener('close',()=>{if(lastTrigger?.isConnected)lastTrigger.focus();});
 window.addEventListener('beforeunload',e=>{if(dirty||paused){e.preventDefault();e.returnValue='';}});
 window.addEventListener('popstate',()=>{const old={view,selected,revision};readRoute();const dest={view,selected,revision};({view,selected,revision}=old);navigate(dest.view,dest.selected,dest.revision,false);});
 window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue!==baseRaw){paused='Another tab changed the saved workspace. This tab is retained; material actions are paused until you review and reload.';render();}});
 window.AD03={M,get state(){return M.clone(s)},get role(){return role},get paused(){return paused},get dirty(){return M.clone(dirty)},get baseRaw(){return baseRaw},key:KEY,render,navigate,commit,validEnvelope,ready:true};
}
function readRoute(){const q=new URLSearchParams(location.hash.slice(1));if(q.has('view')&&tabs.some(t=>t[0]===q.get('view')))view=q.get('view');if(q.has('case'))selected=q.get('case');if(q.has('rev'))revision=q.get('rev')==='latest'?null:Number(q.get('rev'));}
return {init,receiverMode:'Normal',pendingNav:null};
})();
App.init().catch(e=>{document.getElementById('banner').textContent='The demonstration could not initialise: '+e.message;});
